import{_ as t,o,c as a,a3 as n}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"Bring your own key · 换成自己的 key","description":"","frontmatter":{},"headers":[],"relativePath":"own-key.md","filePath":"own-key.md"}'),r={name:"own-key.md"};function d(i,e,l,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="bring-your-own-key-·-换成自己的-key" tabindex="-1">Bring your own key · 换成自己的 key <a class="header-anchor" href="#bring-your-own-key-·-换成自己的-key" aria-label="Permalink to &quot;Bring your own key · 换成自己的 key&quot;">​</a></h1><p><a href="#中文">中文</a> · <a href="#english">English</a></p><p>nanoMuse is free and non-profit. The model behind it costs money, and the developer pays for a starting allowance per account (the app shows the relay&#39;s current figures). When it is gone, there are two ways on that need nothing from nanoMuse: a key of your own at a model provider, or a plan you already pay for — ChatGPT, Claude, Kimi — signed in from the app.</p><p>Every client reads the same list of providers, with what each one covers: <strong>chat</strong>, <strong>the hands</strong> (a model that sees screenshots), <strong>pictures</strong> (the avatar studio) and <strong>clips</strong> (the avatar&#39;s short videos). A feature no configured provider covers is simply not offered, with one sentence saying which providers would — nothing breaks.</p><p>Your sign-in, your invite code and your devices are not affected: the account stays, only the model provider changes. Nothing you say passes through nanoMuse Cloud once your own key or plan is in use.</p><hr><h2 id="中文" tabindex="-1">中文 <a class="header-anchor" href="#中文" aria-label="Permalink to &quot;中文&quot;">​</a></h2><h3 id="先看你在哪" tabindex="-1">先看你在哪 <a class="header-anchor" href="#先看你在哪" aria-label="Permalink to &quot;先看你在哪&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>首选</th><th>一把 key 能做什么</th></tr></thead><tbody><tr><td>中国大陆</td><td><strong>阿里云百炼</strong></td><td>对话、动手、画图、生成视频——四样都在一把 key 下</td></tr><tr><td>海外</td><td><strong>OpenRouter</strong>，其次 <strong>OpenAI</strong></td><td>对话、动手、画图；生成视频目前只有百炼</td></tr></tbody></table><p>百炼只给中国大陆身份注册；海外用户一个 OpenRouter 账号就能用到几百个模型，按量付费。首选之外，下面的每一家都可以单独用，或者和另一家搭配——比如对话用 DeepSeek、画图用智谱。</p><p>对话模型和手的模型是两个设置：对话模型在模型选择里，手的模型在「手的模型」一行（手机：设置 → Hands；网页版 / 桌面版：连接）。手的模型必须能看图；App 里的手的模型列表只列能看图的。</p><h3 id="各家服务商能做什么" tabindex="-1">各家服务商能做什么 <a class="header-anchor" href="#各家服务商能做什么" aria-label="Permalink to &quot;各家服务商能做什么&quot;">​</a></h3><p>对话 = 聊天；动手 = 看截图操作手机和电脑；画图 = 形象工作室的图片；视频 = 形象的短动画。</p><table tabindex="0"><thead><tr><th>服务商</th><th style="text-align:center;">对话</th><th style="text-align:center;">动手</th><th style="text-align:center;">画图</th><th style="text-align:center;">视频</th><th>地区</th><th>申请 key</th></tr></thead><tbody><tr><td>阿里云百炼</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>中国大陆</td><td><a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a></td></tr><tr><td>DeepSeek</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以</td><td><a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Kimi（月之暗面）</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以（国内 / 国际两个版本）</td><td><a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a> · <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a></td></tr><tr><td>智谱 GLM</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>硅基流动</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>火山方舟（豆包）</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a></td></tr><tr><td>MiniMax</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以（国内 / 国际两个版本）</td><td><a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td></tr><tr><td>OpenRouter</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>OpenAI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a></td></tr><tr><td>Anthropic Claude</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a></td></tr><tr><td>Google Gemini</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>xAI Grok</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>Groq</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com</a></td></tr><tr><td>Mistral AI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Ollama / LM Studio / vLLM（本机）</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以</td><td>不需要 key</td></tr></tbody></table><p>「视频」一栏只有百炼，是因为 nanoMuse 的视频生成走的是百炼的接口；其他家的视频模型用的是各自的任务接口，这一轮还没有接。「画图」一栏里，OpenRouter 走的是它的 Image API，模型例如 <code>openai/gpt-image-2</code>；Gemini 用 <code>gemini-2.5-flash-image</code>。</p><p>这张表来自仓库里的目录文件 <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a>——每个客户端、中继都读它，地址、默认模型和「能做什么」都在里面；表里的事实在 2026 年 10 月对照各家文档核过。</p><h3 id="怎么申请-key" tabindex="-1">怎么申请 key <a class="header-anchor" href="#怎么申请-key" aria-label="Permalink to &quot;怎么申请 key&quot;">​</a></h3><p>每家的步骤都是一样的三步：注册 → 控制台里创建 API key → 复制到 nanoMuse。<strong>key 只给 nanoMuse 用，不要发给任何人、不要贴到聊天里。</strong></p><ul><li><strong>阿里云百炼。</strong> 用阿里云账号登录 <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a>（要实名认证），首次进入点「开通百炼服务」，再到 <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY 页</a> 创建；key 以 <code>sk-</code> 开头。新账号有一段时间的免费 token。建议在控制台设一个用量告警。</li><li><strong>DeepSeek。</strong> <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a> 注册、充值、API Keys 里创建。地址 <code>https://api.deepseek.com/v1</code>。</li><li><strong>Kimi。</strong> 国内版在 <a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a>，地址 <code>https://api.moonshot.cn/v1</code>；国际版在 <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a>，地址 <code>https://api.moonshot.ai/v1</code>。两个版本的账号和 key 不通用。</li><li><strong>智谱 GLM。</strong> <a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a>，地址 <code>https://open.bigmodel.cn/api/paas/v4</code>。</li><li><strong>硅基流动。</strong> <a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a>，地址 <code>https://api.siliconflow.cn/v1</code>；模型 id 带厂商前缀，例如 <code>deepseek-ai/DeepSeek-V4-Flash</code>。</li><li><strong>火山方舟。</strong> <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a>，先在方舟里开通要用的模型，再创建 key；地址 <code>https://ark.cn-beijing.volces.com/api/v3</code>。</li><li><strong>MiniMax。</strong> 国内版 <a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a>，地址 <code>https://api.minimaxi.com/v1</code>；国际版地址 <code>https://api.minimax.io/v1</code>。</li><li><strong>OpenRouter。</strong> <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a> 用 Google、GitHub 或邮箱登录，<em>Credits</em> 里充值，<em>Keys</em> 里创建；key 以 <code>sk-or-v1-</code> 开头。<em>Settings → Limits</em> 可以给 key 设每月上限。</li><li><strong>OpenAI。</strong> <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a>，地址 <code>https://api.openai.com/v1</code>。</li><li><strong>Anthropic。</strong> <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a>。nanoMuse 直接用 Anthropic 的接口，不需要兼容层。</li><li><strong>Google Gemini。</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com/apikey</a>，地址 <code>https://generativelanguage.googleapis.com/v1beta/openai</code>。</li><li><strong>xAI、Groq、Mistral。</strong> 各自的控制台创建 key；地址分别是 <code>https://api.x.ai/v1</code>、<code>https://api.groq.com/openai/v1</code>、<code>https://api.mistral.ai/v1</code>。</li></ul><p><strong>贴到 nanoMuse 里。</strong></p><ul><li>手机：额度用完时卡片上的「去设置」会打开预填好的服务商表单；或者 设置 → 服务商 → 添加，选服务商，贴 key，保存。</li><li>网页版 / 桌面版：额度卡片上的「去设置」会打开「连接」页并选好服务商；或者 连接 → 模型，点服务商，贴 key，保存。地址已经填好。</li><li>自己跑的运行时：在 <code>config.toml</code> 里写 <code>[llm] provider = &quot;bailian&quot;</code>（表里任一服务商的 id）加 <code>api_key</code>，地址和默认模型会从目录文件里补上；画图、生成视频用另一家，就加 <code>[image]</code> / <code>[video]</code> 一段（<a href="./configuration#image-and-video">configuration.md</a>）。</li></ul><p>保存后 nanoMuse 列出这把 key 能用的模型：对话选一个，手的模型选一个能看图的；想换形象，再到 连接 → 图像与视频模型 里选。每家的默认模型在目录文件里。</p><h3 id="用你已经在付费的套餐登录" tabindex="-1">用你已经在付费的套餐登录 <a class="header-anchor" href="#用你已经在付费的套餐登录" aria-label="Permalink to &quot;用你已经在付费的套餐登录&quot;">​</a></h3><p>有些套餐可以直接登录使用，不用申请 key：</p><table tabindex="0"><thead><tr><th>套餐</th><th>能做什么</th><th>哪里可以登录</th></tr></thead><tbody><tr><td><strong>ChatGPT</strong>（Plus / Pro / Team）</td><td>对话、动手</td><td>Android、iPhone、桌面版、网页版</td></tr><tr><td><strong>Claude</strong>（Pro / Max）</td><td>对话、动手</td><td>Android、iPhone</td></tr><tr><td><strong>Kimi</strong></td><td>对话、动手</td><td>Android、iPhone（设备码登录）</td></tr><tr><td><strong>OpenRouter</strong></td><td>对话、动手、画图</td><td>Android、iPhone（一键登录，key 自动回到 App）</td></tr></tbody></table><p>ChatGPT 登录走的是 OpenAI 自家 Codex 的授权流程（网页版 / 桌面版：连接 → 「或者用 ChatGPT 套餐登录」；手机：设置 → 服务商 → OpenAI → 登录）。登录后只有对话和动手——Codex 这条通道没有图像和视频接口；画图和生成视频仍要配一把 key。</p><p>在终端里也可以：<code>nanomuse chatgpt login</code> 打开登录页并等浏览器回来，<code>nanomuse chatgpt status</code> 看登录的是谁、什么时候过期，<code>nanomuse chatgpt logout</code> 忘掉它；然后在 <code>config.toml</code> 里写 <code>[llm] provider = &quot;chatgpt&quot;</code>（不用 <code>base_url</code>、<code>api_key</code>，<code>model</code> 留空就是 <code>gpt-5.6-sol</code>）。浏览器要能访问运行时所在机器的 1455 端口；运行时在别的机器上时，把浏览器最后停在的那个地址整条复制下来，贴给命令行的提示，或者 <code>POST /api/chatgpt/callback {&quot;url&quot;: …}</code>（<a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>）。</p><p><strong>一句老实话。</strong> OpenAI 的条款只允许在它自家的 Codex 里使用 ChatGPT 套餐；其他应用曾被切断过这条路（OpenCode，2026 年 1 月）。哪天它不能用了，API key 仍然可以。</p><h3 id="服务商连不上的时候" tabindex="-1">服务商连不上的时候 <a class="header-anchor" href="#服务商连不上的时候" aria-label="Permalink to &quot;服务商连不上的时候&quot;">​</a></h3><p>有些网络到不了 <code>chatgpt.com</code>（DNS 不解析、连接超时、TLS 失败、返回的是一张 HTML 拦截页），有些地区 OpenAI 直接拒绝（HTTP 403 <code>unsupported_country_region_territory</code>）。这时手机上的对话不再显示 socket 原文，而是一张卡片：发生了什么（「这个网络连不上 chatgpt.com」或「OpenAI 不向这个地区提供服务」）、能帮上忙的（这台手机上的 VPN；应用自己的代理，设置 → 网络；换一个服务商、用自己的 key）、一个「重试」按钮，原始错误收在「详情」里供提 issue 用。登录失效（401）显示「ChatGPT 登录已失效」和「重新登录」；套餐这几个小时的余量用完（429 且写明 usage limit）显示「ChatGPT 套餐暂时没有余量了」、OpenAI 自己的那句话和多久后恢复；其他 429 是「同时发出的请求太多」。自己的 key 遇到同样的网络问题，卡片一样出现，只是主机名换成那家服务商的。</p><p><strong>设置 → 网络 → 自有服务商的 HTTP 代理</strong>（Android 和 iPhone 都有）：主机、端口、可选的用户名和密码，默认关闭，只存在这台手机上。只有发往你用自己 key 添加的服务商和 ChatGPT 套餐的请求走它；nanoMuse Cloud、你的电脑和局域网从不经过它。页面上有一行「测试」，通过这个代理抓一次 <code>https://chatgpt.com/</code>，告诉你通没通、多少毫秒。桌面版和运行时的对应项是 <code>config.toml</code> 里的 <code>[llm] proxy</code>（<a href="./configuration#llm">configuration.md</a>）。</p><h3 id="本机模型" tabindex="-1">本机模型 <a class="header-anchor" href="#本机模型" aria-label="Permalink to &quot;本机模型&quot;">​</a></h3><p>Ollama、LM Studio、vLLM 跑在自己电脑上的模型也能用：在「连接」里选对应的预设，地址默认是本机端口（<code>http://127.0.0.1:11434/v1</code>、<code>:1234</code>、<code>:8000</code>），不需要 key。它们算「对话」；手的模型要能看图，本机跑一个多模态模型（例如 Ollama 的 <code>qwen3-vl</code>）再在「手的模型」里手填 id 即可。画图和视频需要上面表里的一家。</p><h3 id="其他-openai-兼容服务" tabindex="-1">其他 OpenAI 兼容服务 <a class="header-anchor" href="#其他-openai-兼容服务" aria-label="Permalink to &quot;其他 OpenAI 兼容服务&quot;">​</a></h3><p>任何 OpenAI 兼容接口都能填，选「自定义」：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>地址（Base URL）</td><td>服务商给的地址，通常以 <code>/v1</code> 结尾</td></tr><tr><td>API key</td><td>服务商控制台里创建的 key（本机服务可以留空）</td></tr><tr><td>模型</td><td>保存后从列表里选；列不出来就手填服务商文档里的模型 id</td></tr></tbody></table><p>自定义接口能做什么由你来说：nanoMuse 会把它当作对话；手的模型、图片模型、视频模型各自填了 id 才算有。</p><hr><h2 id="english" tabindex="-1">English <a class="header-anchor" href="#english" aria-label="Permalink to &quot;English&quot;">​</a></h2><h3 id="where-you-are-decides-who-comes-first" tabindex="-1">Where you are decides who comes first <a class="header-anchor" href="#where-you-are-decides-who-comes-first" aria-label="Permalink to &quot;Where you are decides who comes first&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>First</th><th>What one key there covers</th></tr></thead><tbody><tr><td>Mainland China</td><td><strong>Alibaba Cloud Bailian</strong></td><td>chat, the hands, pictures and clips — all four under one key</td></tr><tr><td>Everywhere else</td><td><strong>OpenRouter</strong>, then <strong>OpenAI</strong></td><td>chat, the hands and pictures; clips are Bailian only for now</td></tr></tbody></table><p>Bailian only signs up accounts with a mainland Chinese identity; outside, one OpenRouter account puts hundreds of models behind one key, pay as you go. Beyond the first pick, every provider below works on its own or beside another — DeepSeek for the chat and Zhipu for pictures, say.</p><p>The chat model and the hands model are two settings: the chat model in the model picker, the hands model on the <em>Hands model</em> row (phone: <em>Settings → Hands</em>; web and desktop: <em>Connections</em>). The hands model has to see pictures; the app&#39;s hands picker lists only models that do.</p><h3 id="what-each-provider-covers" tabindex="-1">What each provider covers <a class="header-anchor" href="#what-each-provider-covers" aria-label="Permalink to &quot;What each provider covers&quot;">​</a></h3><p>Chat = the conversation; hands = reading screenshots to operate the phone or the computer; pictures = the avatar studio&#39;s images; clips = the avatar&#39;s short videos.</p><table tabindex="0"><thead><tr><th>Provider</th><th style="text-align:center;">Chat</th><th style="text-align:center;">Hands</th><th style="text-align:center;">Pictures</th><th style="text-align:center;">Clips</th><th>Region</th><th>Make a key</th></tr></thead><tbody><tr><td>Alibaba Cloud Bailian</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>mainland China</td><td><a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a></td></tr><tr><td>DeepSeek</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both</td><td><a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Kimi (Moonshot AI)</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both (a mainland and a global edition)</td><td><a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a> · <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a></td></tr><tr><td>Zhipu GLM</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>mainland China</td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>SiliconFlow</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>mainland China</td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>Volcengine Ark (Doubao)</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>mainland China</td><td><a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a></td></tr><tr><td>MiniMax</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both (a mainland and a global edition)</td><td><a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td></tr><tr><td>OpenRouter</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>OpenAI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a></td></tr><tr><td>Anthropic Claude</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a></td></tr><tr><td>Google Gemini</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>xAI Grok</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>Groq</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com</a></td></tr><tr><td>Mistral AI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Ollama / LM Studio / vLLM (on your machine)</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both</td><td>no key</td></tr></tbody></table><p>Only Bailian has a dot under <em>Clips</em> because nanoMuse&#39;s clip generation speaks Bailian&#39;s video API; the other vendors&#39; video models sit behind their own task APIs, not wired this round. Under <em>Pictures</em>, OpenRouter goes through its Image API with models such as <code>openai/gpt-image-2</code>; Gemini uses <code>gemini-2.5-flash-image</code>.</p><p>The table is the repository&#39;s catalogue, <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a> — every client and the relay read it; endpoints, default models and what each covers are in there, checked against each vendor&#39;s documentation in October 2026.</p><h3 id="making-a-key" tabindex="-1">Making a key <a class="header-anchor" href="#making-a-key" aria-label="Permalink to &quot;Making a key&quot;">​</a></h3><p>The same three steps everywhere: sign up → create an API key in the console → paste it into nanoMuse. <strong>The key is for nanoMuse only; never send it to anyone or paste it into a chat.</strong></p><ul><li><strong>Alibaba Cloud Bailian.</strong> Sign in to <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a> with an Alibaba Cloud account (identity verification is required), accept <em>Enable Model Studio</em> on first entry, then create a key on the <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY page</a>; it starts with <code>sk-</code>. A new account comes with free tokens for a while. Set a usage alert in the console.</li><li><strong>DeepSeek.</strong> Sign up, add credit and create a key at <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a>; base URL <code>https://api.deepseek.com/v1</code>.</li><li><strong>Kimi.</strong> The mainland edition is <a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a>, base URL <code>https://api.moonshot.cn/v1</code>; the global one is <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a>, base URL <code>https://api.moonshot.ai/v1</code>. Accounts and keys are not shared between the two.</li><li><strong>Zhipu GLM.</strong> <a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a>, base URL <code>https://open.bigmodel.cn/api/paas/v4</code>.</li><li><strong>SiliconFlow.</strong> <a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a>, base URL <code>https://api.siliconflow.cn/v1</code>; model ids carry the vendor prefix, e.g. <code>deepseek-ai/DeepSeek-V4-Flash</code>.</li><li><strong>Volcengine Ark.</strong> <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a> — enable the models you want in Ark, then create a key; base URL <code>https://ark.cn-beijing.volces.com/api/v3</code>.</li><li><strong>MiniMax.</strong> Mainland edition at <a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a>, base URL <code>https://api.minimaxi.com/v1</code>; the global base URL is <code>https://api.minimax.io/v1</code>.</li><li><strong>OpenRouter.</strong> Sign in at <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a> with Google, GitHub or an e-mail address, add credit under <em>Credits</em>, create a key under <em>Keys</em>; it starts with <code>sk-or-v1-</code>. <em>Settings → Limits</em> puts a monthly cap on a key.</li><li><strong>OpenAI.</strong> <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a>, base URL <code>https://api.openai.com/v1</code>.</li><li><strong>Anthropic.</strong> <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a>. nanoMuse speaks Anthropic&#39;s own API; no compatibility layer is needed.</li><li><strong>Google Gemini.</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com/apikey</a>, base URL <code>https://generativelanguage.googleapis.com/v1beta/openai</code>.</li><li><strong>xAI, Groq, Mistral.</strong> A key from each console; base URLs <code>https://api.x.ai/v1</code>, <code>https://api.groq.com/openai/v1</code>, <code>https://api.mistral.ai/v1</code>.</li></ul><p><strong>Paste it into nanoMuse.</strong></p><ul><li>Phone: <em>Set it up</em> on the allowance card opens the provider form pre-filled; or <em>Settings → Providers → Add</em>, pick the provider, paste the key, save.</li><li>Web / desktop: <em>Set it up</em> on the allowance card opens <em>Connections</em> with the provider chosen; or <em>Connections → Model</em>, click the provider, paste the key, save. The address is already filled in.</li><li>A runtime of your own: <code>[llm] provider = &quot;bailian&quot;</code> (any id from the table) and <code>api_key</code> in <code>config.toml</code>; the address and the default model fill in from the catalogue. Pictures or clips from another provider are an <code>[image]</code> / <code>[video]</code> block (<a href="./configuration#image-and-video">configuration.md</a>).</li></ul><p>After saving, nanoMuse lists the models the key can use: pick one for chat and one that sees for the hands; for a new face, choose under <em>Connections → Image &amp; video models</em>. Each provider&#39;s defaults are in the catalogue.</p><h3 id="sign-in-with-a-plan-you-already-pay-for" tabindex="-1">Sign in with a plan you already pay for <a class="header-anchor" href="#sign-in-with-a-plan-you-already-pay-for" aria-label="Permalink to &quot;Sign in with a plan you already pay for&quot;">​</a></h3><p>Some plans sign in directly, with no key to make:</p><table tabindex="0"><thead><tr><th>Plan</th><th>Covers</th><th>Where the sign-in is</th></tr></thead><tbody><tr><td><strong>ChatGPT</strong> (Plus / Pro / Team)</td><td>chat, the hands</td><td>Android, iPhone, desktop, web</td></tr><tr><td><strong>Claude</strong> (Pro / Max)</td><td>chat, the hands</td><td>Android, iPhone</td></tr><tr><td><strong>Kimi</strong></td><td>chat, the hands</td><td>Android, iPhone (device code)</td></tr><tr><td><strong>OpenRouter</strong></td><td>chat, the hands, pictures</td><td>Android, iPhone (one tap; the key comes back to the app)</td></tr></tbody></table><p>The ChatGPT sign-in uses the authorisation flow of OpenAI&#39;s own Codex (web and desktop: <em>Connections → Or sign in with a ChatGPT plan</em>; phone: <em>Settings → Providers → OpenAI → Sign in</em>). Signed in, it covers chat and the hands only — the Codex backend has no image or video endpoints — so pictures and clips still want a key.</p><p>From a terminal it is the same flow: <code>nanomuse chatgpt login</code> opens the page and waits for the browser to come back, <code>nanomuse chatgpt status</code> says who is signed in and until when, <code>nanomuse chatgpt logout</code> forgets it; then <code>[llm] provider = &quot;chatgpt&quot;</code> in <code>config.toml</code> (no <code>base_url</code>, no <code>api_key</code>; an empty <code>model</code> is <code>gpt-5.6-sol</code>). The browser has to reach port 1455 on the machine the runtime runs on; when the runtime is elsewhere, copy the whole address the browser ends on and give it to the CLI&#39;s prompt or to <code>POST /api/chatgpt/callback {&quot;url&quot;: …}</code> (<a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>).</p><p><strong>One honest line.</strong> OpenAI&#39;s terms cover using a ChatGPT plan inside OpenAI&#39;s own Codex; other apps have had this access cut off before (OpenCode, January 2026). If it stops working, an API key does.</p><h3 id="when-the-provider-cannot-be-reached" tabindex="-1">When the provider cannot be reached <a class="header-anchor" href="#when-the-provider-cannot-be-reached" aria-label="Permalink to &quot;When the provider cannot be reached&quot;">​</a></h3><p>Some networks do not get to <code>chatgpt.com</code> at all (the name does not resolve, the connection times out, TLS fails, an HTML interception page comes back where JSON was due), and in some regions OpenAI refuses outright (HTTP 403 <code>unsupported_country_region_territory</code>). The chat on the phone then shows a card, not the socket&#39;s words: what happened (<em>chatgpt.com cannot be reached from this network</em> or <em>OpenAI does not serve this region</em>), what helps (a VPN on this phone; the app&#39;s own proxy under <em>Settings → Network</em>; another provider with a key of your own), a <em>Try again</em> button, and the raw line behind <em>Details</em> for a bug report. An expired sign-in (401) reads <em>The ChatGPT sign-in is no longer valid</em> with <em>Sign in again</em>; a plan whose window is spent (a 429 that names a usage limit) reads <em>The ChatGPT plan has nothing left for now</em> with OpenAI&#39;s own sentence and when it resets; any other 429 is <em>Too many requests at once</em>. A key of your own that meets the same network trouble gets the same card with that provider&#39;s host in it.</p><p><strong>Settings → Network → HTTP proxy for own providers</strong> (Android and iPhone): host, port, an optional user name and password; off by default, kept on this phone only. Only the requests to the providers you added with your own key and to the ChatGPT plan go through it; nanoMuse Cloud, your computers and the local network never do. A <em>Test</em> row fetches <code>https://chatgpt.com/</code> through the proxy as entered and says whether it got through and in how many milliseconds. On the desktop and the runtime the same switch is <code>[llm] proxy</code> in <code>config.toml</code> (<a href="./configuration#llm">configuration.md</a>).</p><h3 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models&quot;">​</a></h3><p>Ollama, LM Studio and vLLM on your own computer work too: pick the preset under <em>Connections</em>; the address defaults to the local port (<code>http://127.0.0.1:11434/v1</code>, <code>:1234</code>, <code>:8000</code>) and no key is needed. They count as <em>chat</em>; the hands need a model that sees, so run a multimodal one locally (Ollama&#39;s <code>qwen3-vl</code>, say) and type its id on the <em>Hands model</em> row. Pictures and clips need one of the providers in the table.</p><h3 id="any-other-openai-compatible-endpoint" tabindex="-1">Any other OpenAI-compatible endpoint <a class="header-anchor" href="#any-other-openai-compatible-endpoint" aria-label="Permalink to &quot;Any other OpenAI-compatible endpoint&quot;">​</a></h3><p>Anything that speaks the OpenAI API works — choose <em>Custom</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Base URL</td><td>the provider&#39;s address, usually ending in <code>/v1</code></td></tr><tr><td>API key</td><td>the key made in the provider&#39;s console (a local server may leave it empty)</td></tr><tr><td>Model</td><td>pick from the list after saving; if none appears, type the model id from the provider&#39;s docs</td></tr></tbody></table><p>What a custom endpoint covers is yours to say: nanoMuse takes it for chat, and the hands, picture and clip models count once their ids are filled in.</p>',69)])])}const m=t(r,[["render",d]]);export{g as __pageData,m as default};
